sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // Add your code here
    if (!current.employeename) {
        // If you want to clear when employee is cleared, uncomment:
        current.manager = '';
        current.manager_email = '';
        return;
    }
    var isInsert = current.operation() === 'insert';
    var employeeChanged = current.employeename.changes();
    var needFill = gs.nil(current.manager) || gs.nil(current.manager_email);
    if (!(isInsert || employeeChanged || needFill)) return;

    // Get the referenced PettyCashUsers record from employeename
    var emp = current.employeename.getRefRecord();
    if (!emp || !emp.isValidRecord()) return;
    var mgrSysId = emp.getValue('manager'); // expects PettyCashUsers.manager = ref to sys_user
    var mgrEmail = emp.getValue('manager_email');

// If email not present there but manager exists, fetch from sys_user
  if (!mgrEmail && mgrSysId) {
    var usr = new GlideRecord('sys_user');
    if (usr.get(mgrSysId)) {
      mgrEmail = usr.getValue('email');
    }
  } 

  // Set fields on pettyCashMain (reference stores sys_id; display handled by platform)
  if (mgrSysId) current.manager = mgrSysId;
  if (mgrEmail) current.manager_email = mgrEmail;

})(current, previous);
